param([string]$Session,[string]$Type,[string]$Since,[int]$Limit=100) $ErrorActionPreference='Stop';$root=Join-Path $env:LOCALAPPDATA 'Harmonia\data';$idx=Get-Content (Join-Path $root 'index.json') -Raw|ConvertFrom-Json;if(-not $Session){$idx.sessions.PSObject.Properties|ForEach-Object{[pscustomobject]@{Session=$_.Name;First=$_.Value.firstAt;Last=$_.Value.lastAt;Events=$_.Value.events;File=$_.Value.file}}|Sort-Object Last -Descending|Format-Table -AutoSize;exit};$s=$idx.sessions.$Session;if(-not $s){throw "Session not found: $Session"};$p=Join-Path $root $s.file;Get-Content $p|ForEach-Object{$_|ConvertFrom-Json}|Where-Object{(-not $Type-or$_.type-like"*$Type*")-and(-not $Since-or[datetime]$_.capturedAt-ge[datetime]$Since)}|Select-Object -First $Limit|ConvertTo-Json -Depth 12